package com.example

/**
 * Complete, distinct 20 cards for Science Sets 5 to 10 (120 unique cards).
 * 100% curriculum aligned with official O/L Science syllabus.
 */
object FlashcardBankScienceSets {

  fun getScienceSet(setNum: Int, cardNum: Int, grade: String): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    val isGr11 = grade.contains("11")
    return when (setNum) {
      5 -> if (isGr11) scienceSet5Gr11[(c - 1) % scienceSet5Gr11.size] else scienceSet5Gr10[(c - 1) % scienceSet5Gr10.size]
      6 -> if (isGr11) scienceSet6Gr11[(c - 1) % scienceSet6Gr11.size] else scienceSet6Gr10[(c - 1) % scienceSet6Gr10.size]
      7 -> if (isGr11) scienceSet7Gr11[(c - 1) % scienceSet7Gr11.size] else scienceSet7Gr10[(c - 1) % scienceSet7Gr10.size]
      8 -> if (isGr11) scienceSet8Gr11[(c - 1) % scienceSet8Gr11.size] else scienceSet8Gr10[(c - 1) % scienceSet8Gr10.size]
      9 -> if (isGr11) scienceSet9Gr11[(c - 1) % scienceSet9Gr11.size] else scienceSet9Gr10[(c - 1) % scienceSet9Gr10.size]
      10 -> if (isGr11) scienceSet10Gr11[(c - 1) % scienceSet10Gr11.size] else scienceSet10Gr10[(c - 1) % scienceSet10Gr10.size]
      else -> null
    }
  }

  // --- SET 5: ඝනත්වය, පීඩනය & උඩුකුරු තෙරපුම (Grade 10) ---
  private val scienceSet5Gr10 = listOf(
    CardContentTuple("ඝනත්වය (Density) අර්ථ දක්වන්න.", "ඒකක පරිමාවක ඇති ස්කන්ධයයි: ρ = m / V. සම්මත SI ඒකකය kg m⁻³ වේ.", "ජලයේ ඝනත්වය 1000 kg m⁻³ (හෝ 1 g cm⁻³) වේ.", "ρ = m / V"),
    CardContentTuple("පීඩනය (Pressure) අර්ථ දක්වන්න.", "ඒකක වර්ගඵලයක් මත අභිලම්භව යෙදෙන බලයයි: P = F / A. ඒකකය Pa (පැස්කල්) හෝ N m⁻².", "වර්ගඵලය අඩු වන විට පීඩනය වැඩි වේ.", "P = F / A"),
    CardContentTuple("නිශ්චල ද්‍රවයක පීඩනය සෙවීමේ සූත්‍රය කුමක්ද?", "P = hρg (මෙහි h = ගැඹුර, ρ = ද්‍රවයේ ඝනත්වය, g = ගුරුත්වජ ත්වරණය).", "ද්‍රව පීඩනය බඳුනේ හැඩය හෝ ද්‍රව ප්‍රමාණය මත රඳා නොපවතී.", "P = hρg"),
    CardContentTuple("පැස්කල්ගේ නියමය (Pascal's Principle) ප්‍රකාශ කරන්න.", "සංවෘත බඳුනක ඇති නිශ්චල ද්‍රවයක කිසියම් ලක්ෂ්‍යයකට යොදන පීඩනය, ද්‍රවය තුළ සෑම දිශාවකටම හා බඳුනේ බිත්ති වෙත නොඅඩුව සම්ප්‍රේෂණය වේ.", "හයිඩ්‍රොලික් තිරිංග සහ එසවුම් උපකරණවල පදනමයි.", "Pascal's Law"),
    CardContentTuple("ආකිමිඩීස් මූලධර්මය (Archimedes' Principle) කුමක්ද?", "වස්තුවක් ද්‍රවයක සම්පූර්ණයෙන් හෝ අර්ධ වශයෙන් ගිලී පවතින විට, ඒ මත ක්‍රියා කරන උඩුකුරු තෙරපුම වස්තුව මගින් විස්ථාපනය කළ ද්‍රවයේ බරට සමාන වේ.", "U = Vρg (උඩුකුරු තෙරපුම = විස්ථාපිත ද්‍රව බර).", "U = Vρg"),
    CardContentTuple("පායන මූලධර්මය (Principle of Floatation) කුමක්ද?", "නිදහසේ පායන වස්තුවක බර, එමගින් විස්ථාපනය වන ද්‍රව පරිමාවේ බරට සමාන වේ (වස්තු බර = උඩුකුරු තෙරපුම).", "නැව් සහ අයිස් කුට්ටි ජලයේ පා වන්නේ මේ නිසාය.", "Floatation Law"),
    CardContentTuple("සම්මත වායුගෝලීය පීඩනය (1 atm) රසදිය මට්ටමෙන් කොපමණද?", "760 mm Hg හෙවත් 76 cm Hg (පැස්කල්වලින් 101,325 Pa හෙවත් 1.013 × 10⁵ Pa).", "ටොරිසෙලි විසින් සරල රසදිය බැරෝමීටරය නිපදවන ලදී.", "760 mm Hg"),
